"use client";

import {
  CSSProperties,
  useEffect,
  useMemo,
  useState,
} from "react";

import {
  serviceCatalog,
  totalServices,
} from "@/data/serviceCatalog";

type ServiceMegaMenuProps = {
  open: boolean;
  onClose: () => void;
};

export function ServiceMegaMenu({
  open,
  onClose,
}: ServiceMegaMenuProps) {
  const [activeSlug, setActiveSlug] = useState(
    serviceCatalog[0].slug
  );

  const [query, setQuery] = useState("");

  const activeGroup =
    serviceCatalog.find(
      (group) => group.slug === activeSlug
    ) ?? serviceCatalog[0];

  const results = useMemo(() => {
    const text = query.trim().toLowerCase();

    if (!text) return [];

    return serviceCatalog.flatMap((group) =>
      group.services
        .filter((service) =>
          service.toLowerCase().includes(text)
        )
        .map((service) => ({
          service,
          group: group.label,
          accent: group.accent,
        }))
    );
  }, [query]);

  useEffect(() => {
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        onClose();
      }
    };

    window.addEventListener("keydown", handleEscape);

    return () =>
      window.removeEventListener(
        "keydown",
        handleEscape
      );
  }, [onClose]);

  useEffect(() => {
    if (!open) {
      setQuery("");
    }
  }, [open]);

  return (
    <>
      <button
        type="button"
        className={`lawx-mega-backdrop ${
          open ? "active" : ""
        }`}
        aria-label="Close services"
        onClick={onClose}
      />

      <div
        className={`lawx-mega ${
          open ? "active" : ""
        }`}
      >
        <div className="lawx-mega-head">
          <div>
            <span>LAWXYGEN SERVICES</span>

            <strong>
              Explore {totalServices} services
            </strong>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="lawx-mega-close"
            aria-label="Close menu"
          >
            ×
          </button>
        </div>

        <div className="lawx-mega-search">
          <span>⌕</span>

          <input
            type="search"
            value={query}
            onChange={(event) =>
              setQuery(event.target.value)
            }
            placeholder="Search GST, trademark, company registration..."
          />

          {query && (
            <button
              type="button"
              onClick={() => setQuery("")}
            >
              Clear
            </button>
          )}
        </div>

        {query ? (
          <div className="lawx-search-results">
            <div className="lawx-result-count">
              {results.length} matching services
            </div>

            <div className="lawx-result-grid">
              {results.map((item) => (
                <a
                  href="#service-universe"
                  onClick={onClose}
                  key={`${item.group}-${item.service}`}
                  className="lawx-result-item"
                >
                  <i
                    style={{
                      background: item.accent,
                    }}
                  />

                  <div>
                    <strong>{item.service}</strong>
                    <span>{item.group}</span>
                  </div>

                  <b>↗</b>
                </a>
              ))}
            </div>

            {!results.length && (
              <div className="lawx-empty-search">
                No matching service found.
              </div>
            )}
          </div>
        ) : (
          <div className="lawx-mega-body">
            <div className="lawx-mega-categories">
              {serviceCatalog.map((group) => (
                <button
                  type="button"
                  key={group.slug}
                  onMouseEnter={() =>
                    setActiveSlug(group.slug)
                  }
                  onClick={() =>
                    setActiveSlug(group.slug)
                  }
                  className={
                    activeSlug === group.slug
                      ? "active"
                      : ""
                  }
                >
                  <i
                    style={{
                      background: group.accent,
                    }}
                  />

                  <span>{group.label}</span>

                  <b>
                    {String(
                      group.services.length
                    ).padStart(2, "0")}
                  </b>
                </button>
              ))}
            </div>

            <div
              className="lawx-mega-services"
              style={
                {
                  "--service-accent":
                    activeGroup.accent,
                } as CSSProperties
              }
            >
              <div className="lawx-mega-service-title">
                <div>
                  <span>Category</span>
                  <h3>{activeGroup.label}</h3>
                </div>

                <strong>
                  {activeGroup.services.length}
                  <small> services</small>
                </strong>
              </div>

              <div className="lawx-mega-service-grid">
                {activeGroup.services.map(
                  (service, index) => (
                    <a
                      href="#service-universe"
                      onClick={onClose}
                      key={service}
                    >
                      <span>
                        {String(index + 1).padStart(
                          2,
                          "0"
                        )}
                      </span>

                      <strong>{service}</strong>

                      <b>↗</b>
                    </a>
                  )
                )}
              </div>
            </div>
          </div>
        )}
      </div>
    </>
  );
}